public static void main(String[] args) {
    Scanner scan = new Scanner(System.in);
    int n = scan.nextInt();
    int maxSize = (int) Math.pow(3, n);
    char[][] result = new char[1][1];
    result[0][0] = '#';
    int size = 3;
    while (size <= maxSize) {
        char[][] array = result;
        result = new char[size][size];
        for (int j = 0; j < array.length; j++) {
            for (int i = 0; i < array.length; i++) {
                extendCarpet(i, j, result, array[i][j]);
            }
        }
        size *= 3;
    }

    for (int j = 0; j < result.length; j++) {
        for (int i = 0; i < result.length; i++) {
            System.out.print(result[j][i]);
        }
        System.out.println();
    }

    scan.close();
}

private static void extendCarpet(int i, int j, char[][] result, char c) {
    int size = result.length / 3;
    for (int y = 0; y < 3; y++) {
        for (int x = 0; x < 3; x++) {
            if (y == 1 && x == 1) {
                result[j * 3 + y][i * 3 + x] = ' ';
            } else {
                result[j * 3 + y][i * 3 + x] = c;
            }
        }
    }
}
